1.9 Code
The snippet prints the noise multipliers of Table 1.1 and sizes a test set.
import math
from statistics import NormalDist


def normal_multiplier(beta: float) -&gt; float:
    """Number of standard deviations a normal draw stays within, except with probability beta."""
    return NormalDist().inv_cdf(1 - beta / 2)


def test_set_size(p: float, relative: float) -&gt; int:
    """Test examples needed for a measured rate near p to have this relative standard deviation."""
    return math.ceil((1 - p) / (p * relative**2))


print(f"{normal_multiplier(0.05):.2f} {normal_multiplier(1e-3):.2f} {normal_multiplier(1e-6):.2f}")  # 1.96 3.29 4.89
print(f"{math.log(1 / 0.05):.2f} {math.log(1 / 1e-3):.2f} {math.log(1 / 1e-6):.2f}")  # 3.00 6.91 13.82
print(test_set_size(0.05, 0.1), test_set_size(0.001, 0.1))  # 1900 99900

2.8 Code
The functions below compute the widths, sample sizes and rate bounds of this chapter, and print the numbers quoted above.
import math
from statistics import NormalDist


def laplace_width(b: float, beta: float, k: int = 1) -&gt; float:
    """All k draws of Lap(b) noise stay within this distance of zero, except with probability beta."""
    return b * math.log(k / beta)


def gaussian_width(sigma: float, beta: float, k: int = 1) -&gt; float:
    """The same for N(0, sigma^2) noise, from the exact normal quantile."""
    return sigma * NormalDist().inv_cdf(1 - beta / (2 * k))


def laplace_sum_width(k: int, b: float, beta: float) -&gt; float:
    """Two-sided width for the sum of k independent Lap(b) noise draws, from the bound."""
    log_term = math.log(2 / beta)
    return max(math.sqrt(8 * k * b**2 * log_term), 4 * b * log_term)


def chernoff_two_sided(mu: float, delta: float) -&gt; float:
    """Chance that a count with mean mu lands more than a fraction delta from it (delta &lt;= 1)."""
    return math.exp(-(delta**2) * mu / (2 + delta)) + math.exp(-(delta**2) * mu / 2)


def hoeffding_n(width: float, beta: float, value_range: float = 1.0) -&gt; int:
    """Samples needed for an average to be within width of its mean, except with probability beta."""
    return math.ceil(value_range**2 * math.log(2 / beta) / (2 * width**2))


def rate_upper_bound(errors: int, n: int, beta: float) -&gt; float:
    """Exact (Clopper-Pearson) one-sided upper bound on a rate measured as errors out of n."""

    def cdf(p: float) -&gt; float:
        return sum(math.comb(n, i) * p**i * (1 - p) ** (n - i) for i in range(errors + 1))

    lo, hi = errors / n, 1.0
    for _ in range(100):
        mid = (lo + hi) / 2
        lo, hi = (mid, hi) if cdf(mid) &gt; beta else (lo, mid)
    return hi


print(f"{laplace_width(2, 0.05):.2f}")  # 5.99
print(f"{laplace_width(2, 0.05, k=1000):.2f}")  # 19.81
print(f"{gaussian_width(2, 0.05):.2f}")  # 3.92
print(f"{laplace_sum_width(10, 1, 0.05):.2f}")  # 17.18
print(f"{chernoff_two_sided(600, 0.2):.1e}")  # 2.4e-05
print(hoeffding_n(0.01, 0.05))  # 18445
print(f"{rate_upper_bound(1, 1000, 0.05):.4f}")  # 0.0047
print(f"{rate_upper_bound(0, 1000, 0.05):.4f}")  # 0.0030

3.10 Code
The functions below compute a discrete KL divergence, the hockey-stick divergence of a normal pair, and the Pinsker floor on a sample size.
import math
from statistics import NormalDist

Z = NormalDist()


def kl(p: list[float], q: list[float]) -&gt; float:
    """KL divergence of P from Q in nats; infinite if Q misses an outcome that P can produce."""
    total = 0.0
    for pi, qi in zip(p, q):
        if pi &gt; 0:
            if qi == 0:
                return math.inf
            total += pi * math.log(pi / qi)
    return total


def gauss_hockey(mu: float, gamma: float) -&gt; float:
    """Hockey-stick divergence E_gamma between N(0, 1) and N(mu, 1)."""
    c = math.log(gamma)
    return Z.cdf(mu / 2 - c / mu) - gamma * Z.cdf(-mu / 2 - c / mu)


def min_samples(kl_one: float, accuracy: float) -&gt; int:
    """Pinsker: no test reaches this accuracy (equal priors) with fewer samples."""
    return math.ceil(2 * (2 * accuracy - 1) ** 2 / kl_one)


def gauss_samples(mu: float, accuracy: float) -&gt; int:
    """Samples the best test needs for N(0, 1) against N(mu, 1), exactly."""
    return math.ceil((2 * Z.inv_cdf(accuracy) / mu) ** 2)


before, after = [0.5, 0.3, 0.2, 0.0], [0.4, 0.3, 0.2, 0.1]
print(f"{kl(before, after):.4f} {kl(after, before)}")  # 0.1116 inf
print(f"{kl(before, after) / math.log(2):.4f}")  # 0.1610
print(f"{gauss_hockey(1.0, 2.0):.4f}")  # 0.1906
print(min_samples(0.005, 0.95), gauss_samples(0.1, 0.95))  # 324 1083

6.9 Code
This calculator gives the step size of convex SGD, with or without gradient noise, and the movement bound for regularized ERM.
import math


def sgd_step(radius: float, lipschitz: float, steps: int, noise: float = 0.0) -&gt; float:
    """Step size that balances the convex SGD bound."""
    return radius / math.sqrt((lipschitz**2 + noise**2) * steps)


def erm_movement(lipschitz: float, lam: float, n: int) -&gt; float:
    """Largest move of the minimizer when one example is replaced."""
    return 2 * lipschitz / (lam * n)


print(f"{sgd_step(5, 1, 10_000):.4f}")  # 0.0500
print(f"{sgd_step(5, 1, 10_000, noise=1):.4f}")  # 0.0354
print(f"{sgd_step(5, 1, 10_000, noise=3):.4f}")  # 0.0158
print(f"{erm_movement(1, 0.1, 1000):.3f}")  # 0.020

12.7 Code
The functions below compute the ceiling, the TV distance between the two binomial counts, and the best membership advantage, and print numbers of Table 12.1.
from math import exp, lgamma, log


def binom_pmf(n: int, t: float) -&gt; list[float]:
    """Pr[Bin(n, t) = k] for k = 0..n, in log space."""
    return [exp(lgamma(n + 1) - lgamma(k + 1) - lgamma(n - k + 1) + k * log(t) + (n - k) * log(1 - t)) for k in range(n + 1)]


def property_ceiling(n: int, t0: float, t1: float) -&gt; float:
    """Best advantage of any property attack when the group is visible: TV(Bin(n, t0), Bin(n, t1))."""
    return 0.5 * sum(abs(p - q) for p, q in zip(binom_pmf(n, t0), binom_pmf(n, t1)))


def membership_best(n: int, t: float) -&gt; float:
    """Best advantage for one subgroup record from the same count: (1 - t) max_k Pr[Bin(n - 1, t) = k]."""
    return (1 - t) * max(binom_pmf(n - 1, t))


print(f"{property_ceiling(100, 0.45, 0.55):.4f} {property_ceiling(1000, 0.45, 0.55):.4f}")  # 0.6827 0.9985
print(f"{membership_best(100, 0.5):.4f} {membership_best(10000, 0.5):.4f}")  # 0.0398 0.0040
