18.9 Code
This snippet prints rows of Table 18.1 and turns a measured attack into a lower bound on \(\varepsilon\).
from math import exp, log


def advantage_bound(eps: float) -&gt; float:
    """The largest TPR - FPR against any eps-DP mechanism."""
    return (exp(eps) - 1) / (exp(eps) + 1)


def posterior_bound(eps: float, prior: float) -&gt; float:
    """The largest posterior after one output of an eps-DP mechanism."""
    return exp(eps) * prior / (exp(eps) * prior + 1 - prior)


def epsilon_lower_bound(tpr: float, fpr: float, delta: float) -&gt; float:
    """The smallest eps consistent with an attack measured at (fpr, tpr)."""
    return log((tpr - delta) / fpr)


print(f"{advantage_bound(3.0):.4f}")  # 0.9051
print(f"{advantage_bound(8.0):.4f}")  # 0.9993
print(f"{posterior_bound(8.0, 0.01):.4f}")  # 0.9679
print(f"{posterior_bound(8.0, 0.5):.4f}")  # 0.9997
print(f"{epsilon_lower_bound(0.05, 1e-3, 1e-5):.2f}")  # 3.91

20.7 Code
The analytic calibration needs only the normal CDF, which math.erfc provides. The snippet also computes Laplace error bars.
from math import erfc, exp, log, sqrt


def normal_cdf(x: float) -&gt; float:
    return 0.5 * erfc(-x / sqrt(2))


def gaussian_delta(eps: float, mu: float) -&gt; float:
    """The exact delta of the Gaussian mechanism at eps, where mu = sensitivity / sigma."""
    return normal_cdf(mu / 2 - eps / mu) - exp(eps) * normal_cdf(-mu / 2 - eps / mu)


def analytic_sigma(eps: float, delta: float, sensitivity: float = 1.0) -&gt; float:
    """The smallest sigma for which the Gaussian mechanism is (eps, delta)-DP."""
    lo, hi = 1e-6, 100.0  # gaussian_delta grows with mu: bisect for gaussian_delta(eps, mu) = delta
    for _ in range(60):
        mid = (lo + hi) / 2
        lo, hi = (mid, hi) if gaussian_delta(eps, mid) &lt; delta else (lo, mid)
    return sensitivity / lo


def laplace_width(scale: float, beta: float, d: int = 1) -&gt; float:
    """All d coordinates of Lap(scale) noise stay within this width, except with probability beta."""
    return scale * log(d / beta)


print(f"{analytic_sigma(1.0, 1e-5):.4f}")  # 3.7306
print(f"{analytic_sigma(0.1, 1e-5):.4f}")  # 30.7496
print(f"{laplace_width(1 / 0.1, 0.05):.2f}")  # 29.96
print(f"{log(1 / 0.05) / 10:.4f}")  # 0.2996

28.6 Code
The snippet computes the records a bounded mean needs and the default clipping width for heavy tails.
from math import ceil, log, sqrt


def records_for_bounded_mean(alpha: float, sd: float, width: float, eps: float) -&gt; int:
    """Smallest n with sd^2/n + 2 (width/(n eps))^2 &lt;= alpha^2."""
    a, c = sd**2, 2 * (width / eps) ** 2
    return ceil((a + sqrt(a * a + 4 * c * alpha**2)) / (2 * alpha**2))


def heavy_tail_width(n: int, eps: float, sd: float) -&gt; float:
    """The clipping half-width that balances the bias bound sd^2/tau against the noise."""
    return sd * sqrt(n * eps / (2 * sqrt(2)))


print(records_for_bounded_mean(0.05, 0.5, 1.0, 1.0))  # 108
print(f"{heavy_tail_width(1000, 1.0, 1.0):.2f}")  # 18.80

30.8 Code
This snippet converts the single release’s curve on the part’s grid of orders at three values of \(\delta\). To convert another mechanism, replace the curve by its RDP values on the same grid.
from math import log

ORDERS = [1 + x / 10 for x in range(1, 100)] + list(range(12, 64)) + [128, 256, 512]


def mironov(rdp: float, alpha: float, delta: float) -&gt; float:
    return rdp + log(1 / delta) / (alpha - 1)


def improved(rdp: float, alpha: float, delta: float) -&gt; float:
    """Balle et al. (2020); Canonne, Kamath & Steinke (2020). Clipped at 0."""
    return max(0.0, rdp + log((alpha - 1) / alpha) - (log(delta) + log(alpha)) / (alpha - 1))


def report(mu: float, delta: float = 1e-5) -&gt; str:
    """Both conversions for a composed Gaussian with mu = sqrt(steps) / sigma."""
    curve = [a * mu**2 / 2 for a in ORDERS]
    mir = min((mironov(e, a, delta), a) for a, e in zip(ORDERS, curve))
    imp = min((improved(e, a, delta), a) for a, e in zip(ORDERS, curve))
    return "Mironov %.3f at order %g, improved %.3f at order %g" % (*mir, *imp)


print(report(1.0))  # Mironov 5.299 at order 5.8, improved 4.729 at order 5.4
print(report(1.0, 1e-6))  # Mironov 5.757 at order 6.3, improved 5.222 at order 5.9
print(report(1.0, 1e-8))  # Mironov 6.570 at order 7.1, improved 6.086 at order 6.7
